<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { me } from '../api';
import { courseApi, all, errorText, tag, type Employee, type Page, type Salary } from '../course-api';
const month=ref(new Date().toISOString().slice(0,7)), filter=ref(''), hr=ref(false), employees=ref<Employee[]>([]), items=ref<Salary[]>([]), history=ref<{version_no:number;amount:string;recorded_at:string}[]>([]), busy=ref(false), error=ref(''), notice=ref(''), page=ref(1),total=ref(0),selected=ref<Salary|null>(null);
const form=ref({employee_id:'',month:month.value,amount:''});
const name=(id:string)=>employees.value.find(e=>e.id===id)?.full_name||id;
async function load(){busy.value=true;error.value='';try{const query=new URLSearchParams({page:String(page.value),page_size:'20',...(month.value?{month:month.value}:{}),...(filter.value?{employee_id:filter.value}:{})});const data=await courseApi<Page<Salary>>(`/salaries?${query}`);items.value=data.items;total.value=data.total;}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function edit(row:Salary){selected.value=row;form.value={employee_id:row.employee_id,month:row.month,amount:row.amount};history.value=[];}
async function revisions(row:Salary){error.value='';try{history.value=(await courseApi<{items:typeof history.value}>(`/salaries/${encodeURIComponent(row.id)}/history`)).items;}catch(e){error.value=errorText(e);}}
async function save(){busy.value=true;error.value='';try{await courseApi('/salaries','PUT',form.value,selected.value?tag(selected.value):undefined);notice.value='月度应发工资已保存，修订记录已留存';selected.value=null;form.value.amount='';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
onMounted(async()=>{try{hr.value=(await me()).roles.includes('HR');if(hr.value)employees.value=await all<Employee>('/employees');await load();}catch(e){error.value=errorText(e);}});
</script>
<template><div class="workspace"><header><span class="brand">HRMS</span><span>月度薪资</span><router-link class="back-link" to="/">返回主页</router-link></header><main><h1>{{hr?'薪资管理':'我的薪资'}}</h1><p class="muted">人民币月度应发总额，由 HR 手工录入；不计算个税社保，不执行实际支付。</p><p v-if="error" class="error feedback" role="alert">{{error}}</p><p v-if="notice" class="success feedback" role="status">{{notice}}</p>
<section class="card"><form class="search-row" @submit.prevent="page=1;load()"><label>月份<input v-model="month" type="month"></label><label v-if="hr">员工<select aria-label="员工" v-model="filter"><option value="">全部</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.employee_no}} · {{e.full_name}}</option></select></label><button :disabled="busy">查询</button></form><p v-if="busy" role="status">加载中…</p><p v-else-if="!items.length" class="muted">当前范围暂无薪资记录。</p><div v-else class="table-scroll"><table><thead><tr><th>员工</th><th>月份</th><th>应发总额（元）</th><th v-if="hr">操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td>{{name(row.employee_id)}}</td><td>{{row.month}}</td><td class="money">{{row.amount}}</td><td v-if="hr"><button class="text-button" @click="edit(row)">修订</button><button class="text-button" @click="revisions(row)">历史</button></td></tr></tbody></table></div><nav class="pagination"><span>共 {{total}} 条</span><button :disabled="busy||page<=1" @click="page--;load()">上一页</button><button :disabled="busy||page*20>=total" @click="page++;load()">下一页</button></nav>
<div v-if="history.length"><h3>敏感修订历史（仅 HR）</h3><ul><li v-for="r in history" :key="r.version_no">版本 {{r.version_no}} · {{r.amount}} 元 · {{r.recorded_at}}</li></ul></div></section>
<section v-if="hr" class="card"><h2>{{selected?'修订月薪':'录入月薪'}}</h2><form @submit.prevent="save"><fieldset :disabled="busy"><div class="form-columns"><label>员工<select aria-label="员工" v-model="form.employee_id" required :disabled="!!selected"><option disabled value="">请选择</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.employee_no}} · {{e.full_name}}</option></select></label><label>月份<input v-model="form.month" type="month" required :disabled="!!selected"></label><label>应发总额（元）<input v-model="form.amount" inputmode="decimal" pattern="(?:0|[1-9][0-9]{0,9})(?:\.[0-9]{1,2})?" required placeholder="0.00" maxlength="13"></label></div><p class="muted">仅接受非负金额，最多两位小数；同员工同月已有记录时，请先查询后点“修订”。</p><div class="form-actions"><button>保存薪资</button><button type="button" class="secondary" @click="selected=null;form.amount=''">新建 / 取消修订</button></div></fieldset></form></section>
</main></div></template>
